/* Treasure Cove: isolated presentation and lifecycle for Treasure Takeaway. */
const COVE_ID='board-treasure-takeaway';
const COVE_CAPTAINS=['Aisulu','Nuray','Aigerim','Meerim','Akmaral','Azamat','Nursultan','Adilet','Emir','Bek'];
function coveActive(){return game?.lesson.format===COVE_ID;}
function coveReduced(){return arcade.reduced||matchMedia('(prefers-reduced-motion: reduce)').matches;}
// Shared generated 5 × 2 atlas keeps portraits consistent in every game view.
let covePortraitSerial=0;
function coveAvatar(i){
 i=Math.max(0,Math.min(9,i|0));
 const clip='cove-portrait-'+(++covePortraitSerial),x=8-(i%5)*144,y=-Math.floor(i/5)*180;
 return '<svg viewBox="0 0 160 180" width="150" height="180" aria-hidden="true"><defs><pattern id="'+clip+'" patternUnits="userSpaceOnUse" x="8" y="0" width="144" height="180"><image href="./assets/treasure-cove/student-portraits.png" x="'+(x-8)+'" y="'+y+'" width="720" height="360" preserveAspectRatio="none"/></pattern></defs><rect x="8" width="144" height="180" rx="20" fill="url(#'+clip+')"/></svg>';
}
function coveGem(x,y,scale=1,extra=''){return `<g ${extra} transform="translate(${x} ${y}) scale(${scale})"><ellipse cy="25" rx="30" ry="6" fill="#73552c25"/><path d="M-32 -5L-18 -24H18L32 -5L0 27Z" fill="url(#cove-jewel)" stroke="#157d94" stroke-width="2"/><path d="M-32 -5H32M-18 -24L0 27L18 -24M-18 -24L-12 -5L0 27L12 -5L18 -24" fill="none" stroke="#b8fff5" stroke-width="2"/><path d="M-16 -19H-6L-13 -9H-23Z" fill="white" opacity=".8"/></g>`;}
function coveChest(x,side,count,landed){return `<g class="cove-chest ${landed?'landed':''}" transform="translate(${x} 390)"><ellipse cy="70" rx="86" ry="11" fill="#74563335"/><path d="M-73 -10Q-75 -73 0 -73Q75 -73 73 -10Z" fill="#81462a" stroke="#563521" stroke-width="5"/><path d="M-64 -13Q-65 -60 0 -60Q65 -60 64 -13Z" fill="#412f25"/><path d="M-72 0H72L64 64H-64Z" fill="url(#cove-wood)" stroke="#654225" stroke-width="5"/><path d="M-48 0L-43 62M48 0L43 62" stroke="#f4c264" stroke-width="12"/><path d="M-69 10H69" stroke="#ffdb7c" stroke-width="6"/><rect x="-12" y="15" width="24" height="27" rx="5" fill="#ffe08a" stroke="#9b672c" stroke-width="2"/><circle cy="27" r="4" fill="#6c462b"/><text y="96" text-anchor="middle" fill="#254d60" font-size="20" font-weight="800">${count} collected</text></g>`;}
function coveGrid(d){const cols=d.total<=12?4:d.total<=20?5:d.total<=30?6:10,rows=Math.ceil(d.total/cols),gapX=Math.min(95,520/cols),gapY=Math.min(72,230/rows),scale=Math.min(1,gapX/75,gapY/60);return Array.from({length:d.total},(_,i)=>({x:600+(i%cols-(cols-1)/2)*gapX,y:255+(Math.floor(i/cols)-(rows-1)/2)*gapY,scale}));}
const coveInitBase=LAB_ENGINES.boardplay.init;
LAB_ENGINES.boardplay.init=function(c,...args){const d=coveInitBase(c,...args);if(c.variant==='takeaway'){const s=game.lesson.settings;d.total=(s.treasureMin??10)+Math.floor(Math.random()*((s.treasureMax??20)-(s.treasureMin??10)+1));Object.assign(d,{remaining:d.total,players:[{name:'',avatar:0},{name:'',avatar:1}],setup:true,editing:null,coveMotion:null,victory:null,paused:false});}return d;};
const coveEditorBase=setupModeEditor;setupModeEditor=function(){coveEditorBase();if(draft?.format!==COVE_ID)return;$('#mode-setup').insertAdjacentHTML('beforeend',`<div class="cove-teacher"><strong>Treasure Cove · gem settings</strong><p>A fresh random amount each round. Use 1–60 gems; choose the same minimum and maximum for a fixed amount.</p><label>Minimum gems<input id="cove-min" type="number" min="1" max="60" step="1" value="${draft.settings.treasureMin??10}"></label><label>Maximum gems<input id="cove-max" type="number" min="1" max="60" step="1" value="${draft.settings.treasureMax??20}"></label><p>Students enter their names and choose their captains when the game starts.</p></div>`);};
const coveSettingsBase=readModeSettings;readModeSettings=function(){const s=coveSettingsBase();if(draft?.format===COVE_ID)Object.assign(s,{treasureMin:Number($('#cove-min')?.value??draft.settings.treasureMin??10),treasureMax:Number($('#cove-max')?.value??draft.settings.treasureMax??20)});return s;};
function coveChoices(owner,d){return `<div class="cove-choices" role="group" aria-label="Player ${owner+1} avatars">${COVE_CAPTAINS.map((name,i)=>`<button type="button" data-cove-avatar="${i}" data-owner="${owner}" aria-label="${name}" aria-pressed="${d.players[owner].avatar===i}">${coveAvatar(i)}<span>${name}</span></button>`).join('')}</div>`;}
function coveSetup(d){return `<div class="cove-onboard"><span class="cove-kicker">WELCOME TO TREASURE COVE</span><h2>Choose your captains</h2><p>Take 1, 2 or 3 gems. Take the last gem to win!</p><form id="cove-start-form"><div class="cove-students">${[0,1].map(i=>`<section><label for="cove-name-${i}">Player ${i+1} · your name</label><input id="cove-name-${i}" data-cove-name="${i}" maxlength="30" required autocomplete="off" placeholder="Type your name" value="${esc(d.players[i].name)}">${coveChoices(i,d)}</section>`).join('')}</div><button class="cove-primary" type="submit">Set sail →</button></form></div>`;}
function coveStage(d){const moving=d.coveMotion,win=d.victory;let gems='';coveGrid(d).forEach((p,i)=>{if(i<d.remaining)gems+=coveGem(p.x,p.y,p.scale);else if(moving&&i<moving.before){const k=i-d.remaining,t=Math.max(0,Math.min(1,(moving.age-k*.12)/.7)),e=1-Math.pow(1-t,3),x=p.x+((moving.owner?1050:150)-p.x)*e,y=p.y+(375-p.y)*e-Math.sin(t*Math.PI)*125;gems+=coveGem(x,y,p.scale*(1-t*.75),`opacity="${t>=1?0:1}"`);}});
 return `<svg class="cove-stage" viewBox="0 0 1200 540" role="group" aria-label="${d.remaining} gems left. ${esc(d.players[d.turn].name)}'s turn."><defs><linearGradient id="cove-jewel" x2=".8" y2="1"><stop stop-color="#c1fff2"/><stop offset=".35" stop-color="#38d9d9"/><stop offset="1" stop-color="#0089a7"/></linearGradient><linearGradient id="cove-wood" x2="0" y2="1"><stop stop-color="#c28b46"/><stop offset="1" stop-color="#86522b"/></linearGradient></defs><ellipse cx="600" cy="295" rx="330" ry="178" fill="#fff3cb" fill-opacity=".92" stroke="#e8c17b" stroke-width="5"/><path d="M320 405Q600 440 880 405" fill="none" stroke="#cfac6b" stroke-width="3" stroke-dasharray="5 10"/>${[0,1].map(i=>{const x=i?1050:150,active=d.turn===i&&!win;return `<g><circle cx="${x}" cy="190" r="98" fill="${i?'#f3ad89':'#8ed8f1'}" fill-opacity=".8" stroke="${active?'#ffe184':'#ffffff99'}" stroke-width="${active?9:3}"/><g class="cove-captain" style="visibility:${win&&win.owner===i?'hidden':'visible'}" data-cove-edit="${i}" role="button" tabindex="${moving||win?-1:0}" aria-label="Change ${esc(d.players[i].name)}'s avatar" transform="translate(${x-75} 95)">${coveAvatar(d.players[i].avatar)}</g><rect x="${x-120}" y="282" width="240" height="46" rx="12" fill="${i?'#b94e40':'#216795'}" stroke="#ffda7e" stroke-width="3"/><text x="${x}" y="312" text-anchor="middle" fill="white" font-weight="800" font-size="${d.players[i].name.length>18?17:23}">${esc(d.players[i].name)}</text>${coveChest(x,i,d.score[i],d.landed===i)}</g>`;}).join('')}${gems}<text x="600" y="470" text-anchor="middle" font-size="43" font-weight="900" fill="#204b62">${d.remaining} gems left</text><text x="600" y="504" text-anchor="middle" font-size="20" fill="#476373">Take the last gem to win</text></svg>`;
}
function coveWin(d){const v=d.victory,t=Math.min(1,v.age/.8),x=(v.owner?87.5:12.5)+(50-(v.owner?87.5:12.5))*t,y=30+(43-30)*t;return `<div class="cove-victory ${v.age>=.8?'dancing':''}" role="status"><div class="cove-confetti" aria-hidden="true">${Array.from({length:26},(_,i)=>`<i style="--x:${(i*37)%100}%;--d:${i%7*.13}s;--c:${['#ffda70','#5ce3cf','#f38f7e','#a6b4ff'][i%4]}"></i>`).join('')}</div><div class="cove-champion" style="left:${x}%;top:${y}%;--size:${150+100*t}px">${coveAvatar(d.players[v.owner].avatar)}<span class="cove-crown">★</span></div><div class="cove-win-caption"><h2>${esc(d.players[v.owner].name)} wins!</h2><p>You collected the last gem!</p><button class="cove-primary" data-cove-rematch>Play again</button><button class="cove-secondary" data-cove-new>New captains</button></div></div>`;}
const coveRenderBase=labRender;labRender=function(){if(!coveActive())return coveRenderBase();const d=game.session.data;$('#play-title').textContent='Treasure Takeaway';$('#play-subtitle').textContent='Treasure Cove';$('#scoreboard').innerHTML='';$('.player-bottom>span').textContent='Take 1, 2 or 3 gems. The last gem wins.';$('#arena').classList.add('activity-arena');$('#arena').innerHTML=`<section class="cove-game ${d.setup?'is-setup':''}">${d.setup?coveSetup(d):`<header class="cove-header"><div><span class="cove-kicker">TREASURE TAKEAWAY</span><h2>Treasure Cove</h2></div><div class="cove-toolbar"><button data-cove-pause ${d.victory?'disabled':''}>${d.paused?'Resume':'Pause'}</button><button data-cove-settings ${d.coveMotion||d.victory?'disabled':''}>⚙ Settings</button></div></header><div class="cove-turn" role="status">${!d.victory?'<span class="cove-turn-avatar" aria-hidden="true">'+coveAvatar(d.players[d.coveMotion?.owner??d.turn].avatar)+'</span>':''}<span>${d.victory?'A treasure champion!':d.paused?'Adventure paused':d.coveMotion?esc(d.players[d.coveMotion.owner].name)+' is collecting…':esc(d.players[d.turn].name)+'’s turn'}</span></div>${coveStage(d)}<div class="cove-actions">${[1,2,3].map(n=>`<button data-mode-action="lab-take" data-value="${n}" ${d.paused||d.coveMotion||d.victory||n>d.remaining?'disabled':''}>Take ${n}<small>${'◆'.repeat(n)}</small></button>`).join('')}</div>${d.victory?coveWin(d):''}${d.paused?'<div class="cove-pause-shade"><h2>Adventure paused</h2><button class="cove-primary" data-cove-pause>Resume</button></div>':''}`}</section>`;
 $('#cove-start-form')?.addEventListener('submit',e=>{e.preventDefault();if(!e.target.reportValidity())return;const names=d.players.map(p=>p.name.trim());if(names.some(n=>!n)){notify('Each captain needs a name.');return;}d.players.forEach((p,i)=>p.name=names[i]);d.setup=false;coveRender();});
};
function coveRender(){labRender();}
const coveHandleBase=labHandle;labHandle=function(button){if(!coveActive())return coveHandleBase(button);const d=game.session.data,n=Number(button.dataset.value);if(button.dataset.modeAction!=='lab-take'||button.disabled||d.setup||d.paused||d.editing!==null||d.coveMotion||d.victory||![1,2,3].includes(n)||n>d.remaining||ui.view!=='player')return;d.coveMotion={owner:d.turn,before:d.remaining,count:n,age:0};d.remaining-=n;game.session.moves++;d.landed=null;coveRender();};
function covePaint(){const old=$('.cove-stage');if(!old)return;const d=game.session.data;const t=document.createElement('template');t.innerHTML=coveStage(d);old.replaceWith(t.content.firstElementChild);const v=$('.cove-victory');if(v){t.innerHTML=coveWin(d);v.replaceWith(t.content.firstElementChild);}}
const coveStepBase=stepArcade;stepArcade=function(dt){coveStepBase(dt);if(!coveActive()||ui.view!=='player')return;const d=game.session.data;if(d.paused||d.editing!==null)return;if(d.coveMotion){d.coveMotion.age+=dt;const m=d.coveMotion;if(m.age>=(coveReduced()?.16:.8+(m.count-1)*.12)){d.score[m.owner]+=m.count;d.coveMotion=null;d.landed=m.owner;if(d.remaining===0){d.victory={owner:m.owner,age:coveReduced()?1:0};game.session.message=d.players[m.owner].name+' wins!';game.correct=1;game.score=100;game.answered=true;game.done=true;game.celebration={finished:true};}else d.turn=1-m.owner;coveRender();}else covePaint();}else if(d.victory&&d.victory.age<1){d.victory.age+=dt;covePaint();}};
function coveRestart(newPlayers=false){const d=game.session.data,players=clone(d.players);game.done=false;game.celebration=null;game.answered=false;game.score=0;game.correct=0;game.session.message='';game.session.moves=0;game.session.data=LAB_ENGINES.boardplay.init(game.session.config);if(!newPlayers){game.session.data.players=players;game.session.data.setup=false;}coveRender();}
function coveDialog(kind,owner){const d=game.session.data;if(d.coveMotion||d.victory||d.paused)return;$('#cove-dialog')?.remove();const el=document.createElement('dialog');el.id='cove-dialog';el.className='cove-dialog';d.editing=owner??-1;el.innerHTML=kind==='avatar'?`<h2>${esc(d.players[owner].name)} · choose your captain</h2>${coveChoices(owner,d)}<button class="cove-primary" data-cove-close>Done</button>`:`<form id="cove-range-form"><h2>Teacher settings</h2><p>Gem range for the next round (1–60).</p><label>Minimum gems<input id="cove-round-min" type="number" min="1" max="60" required step="1" value="${game.lesson.settings.treasureMin??10}"></label><label>Maximum gems<input id="cove-round-max" type="number" min="1" max="60" required step="1" value="${game.lesson.settings.treasureMax??20}"></label><p id="cove-range-error" role="alert"></p><button class="cove-primary" type="submit">Save for next round</button><button type="button" data-cove-close>Cancel</button></form>`;document.body.append(el);const close=()=>{d.editing=null;el.close();el.remove();coveRender();document.querySelector(`[data-cove-edit="${owner}"]`)?.focus();};el.addEventListener('cancel',e=>{e.preventDefault();close();});el.querySelector('[data-cove-close]').onclick=close;el.querySelector('form')?.addEventListener('submit',e=>{e.preventDefault();const min=Number($('#cove-round-min').value),max=Number($('#cove-round-max').value);if(!Number.isInteger(min)||!Number.isInteger(max)||min<1||max>60||min>max){$('#cove-range-error').textContent='Use whole numbers from 1 to 60. Minimum must not exceed maximum.';return;}Object.assign(game.lesson.settings,{treasureMin:min,treasureMax:max});Object.assign(draft.settings,{treasureMin:min,treasureMax:max});dirty=true;close();notify('Gem range saved for the next round.');});el.showModal();}
document.addEventListener('input',e=>{if(coveActive()&&e.target.matches('[data-cove-name]'))game.session.data.players[Number(e.target.dataset.coveName)].name=e.target.value;});
document.addEventListener('click',e=>{const b=e.target.closest('[data-cove-avatar],[data-cove-edit],[data-cove-pause],[data-cove-settings],[data-cove-rematch],[data-cove-new]');if(!b||!coveActive()||ui.view!=='player')return;const d=game.session.data;if(b.hasAttribute('data-cove-avatar')){const owner=Number(b.dataset.owner);d.players[owner].avatar=Number(b.dataset.coveAvatar);const group=b.closest('.cove-choices');group.querySelectorAll('button').forEach(n=>n.setAttribute('aria-pressed',n===b));}else if(b.hasAttribute('data-cove-edit'))coveDialog('avatar',Number(b.dataset.coveEdit));else if(b.hasAttribute('data-cove-pause')&&!d.victory){d.paused=!d.paused;coveRender();}else if(b.hasAttribute('data-cove-settings'))coveDialog('settings');else if(b.hasAttribute('data-cove-rematch'))coveRestart();else if(b.hasAttribute('data-cove-new'))coveRestart(true);});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-cove-edit]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
const coveShowBase=show;show=function(view){if(view!=='player'){$('#cove-dialog')?.remove();if(coveActive())game.session.data.editing=null;}return coveShowBase(view);};
